"""Build the Russian PDF report for the crossing benchmark.  python build_report.py -> bench/Отчёт_пересечения_2026-09-05.pdf"""
import os, pandas as pd, cv2
from reportlab.lib.pagesizes import A4
from reportlab.lib.units import mm
from reportlab.lib.styles import ParagraphStyle
from reportlab.lib import colors
from reportlab.platypus import SimpleDocTemplate, Paragraph, Spacer, Image, Table, TableStyle, PageBreak, KeepTogether
from reportlab.pdfbase import pdfmetrics
from reportlab.pdfbase.ttfonts import TTFont
from common import ROOT

F = "/usr/share/fonts/truetype/dejavu/"
pdfmetrics.registerFont(TTFont("DV", F + "DejaVuSans.ttf")); pdfmetrics.registerFont(TTFont("DVB", F + "DejaVuSans-Bold.ttf"))
pdfmetrics.registerFont(TTFont("DVI", F + "DejaVuSans-Oblique.ttf"))
RES = f"{ROOT}/bench/results"; MOR = f"{ROOT}/bench/morpho"; OUT = f"{ROOT}/bench/Отчёт_пересечения_2026-09-05.pdf"
H1 = ParagraphStyle("h1", fontName="DVB", fontSize=17, leading=22, spaceAfter=8, spaceBefore=10)
H2 = ParagraphStyle("h2", fontName="DVB", fontSize=13, leading=17, spaceAfter=5, spaceBefore=12)
P = ParagraphStyle("p", fontName="DV", fontSize=10, leading=14.5, spaceAfter=6)
SM = ParagraphStyle("sm", fontName="DVI", fontSize=8.5, leading=11.5, textColor=colors.HexColor("#444444"), spaceAfter=8)
TC = ParagraphStyle("tc", fontName="DV", fontSize=8.5, leading=11)
W = A4[0] - 30*mm

def img(path, width=W, maxh=None):
    im = cv2.imread(path); h, w = im.shape[:2]; ih = width * h / w
    if maxh and ih > maxh: ih = maxh; width = ih * w / h
    return Image(path, width=width, height=ih)
def table(df, colw=None):
    data = [[Paragraph(str(c), TC) for c in df.columns]] + [[Paragraph(str(x), TC) for x in r] for r in df.values]
    t = Table(data, colWidths=colw, repeatRows=1)
    t.setStyle(TableStyle([("FONT", (0, 0), (-1, -1), "DV", 8.5), ("BACKGROUND", (0, 0), (-1, 0), colors.HexColor("#e8eef7")),
                           ("LINEBELOW", (0, 0), (-1, 0), 0.8, colors.HexColor("#2a78d6")), ("LINEBELOW", (0, 1), (-1, -1), 0.25, colors.HexColor("#cccccc")),
                           ("VALIGN", (0, 0), (-1, -1), "MIDDLE"), ("TOPPADDING", (0, 0), (-1, -1), 2), ("BOTTOMPADDING", (0, 0), (-1, -1), 2)]))
    return t

syn = pd.read_csv(f"{RES}/summary_synth.csv"); real = pd.read_csv(f"{RES}/summary_real.csv")
names = {"M0_pipeline": "M0 текущий пайплайн", "M1_graph": "M1 граф скелета", "M2_watershed": "M2 эрозия+watershed", "M3_combo": "M3 M1→M2",
         "OMNI_worm_omni_s0.3": "Omnipose worm_omni (предобуч.)"}
piv = syn.pivot(index="method", columns="type", values="all_recovered")[["ALL", "X", "shallow", "parallel", "tip"]].reset_index()
piv["method"] = piv.method.map(names); piv.columns = ["метод", "все типы", "X (60–120°)", "острый (15–45°)", "параллельно", "кончик"]
piv = piv.round(2)
allrow = syn[syn.type == "ALL"][["method", "base_ok", "donor_ok", "extra", "miss", "err"]].copy(); allrow["method"] = allrow.method.map(names)
allrow.columns = ["метод", "базовый червь найден", "вклеенный найден", "лишних / кадр", "пропущено / кадр", "медианная ошибка, доли L"]
allrow = allrow.round(2)
rt = real.reset_index(); rt["method"] = rt.method.map(names)
rt = rt[["method", "worms_per_frame", "plausible_per_frame", "two_plus", "count_ok"]]
rt.columns = ["метод", "линий / кадр", "правдоподобных (0.6–1.3 L) / кадр", "доля кадров с ≥2", "число совпало с контекстом"]; rt = rt.round(2)

